// Random Wilcoxon rank statistics: rsignrank and rwilcox.
// Generated by definition (signs chosen by uniforms; ranks sampled without replacement).
// Uniform consumption follows observed R output.
import { unifIndex, unifRand } from "./rng.js";
import { generate } from "./common.js";
import { roundHalfEven } from "../internal/integer.js";
/**
 * Random numbers from the distribution of the Wilcoxon signed rank statistic.
 * Equivalent to R's `rsignrank()`.
 *
 * @param nn Number of values to generate.
 * @param n Number of observations in the sample.
 * @returns An array of `nn` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rsignrank(5, 10); // [37, 33, 13, 29, 40]
 * ```
 *
 * @category Random numbers
 */
export function rsignrank(nn, n) {
    return generate(nn, () => {
        // an infinite n would never end the loop below (R's (int) cast of it is undefined)
        if (!Number.isFinite(n))
            return NaN;
        // as R's R_forceint (nearbyint): halves go to the even integer
        const k = roundHalfEven(n);
        if (k < 0)
            return NaN;
        if (k === 0)
            return 0;
        // one uniform per rank: bounded to the domain of dsignrank (about 4 s here; R runs to 2147483647)
        if (k >= 2 ** 27)
            throw new RangeError("n must be less than 2^27 (134217728)");
        let r = 0;
        // Choose the sign of rank i with a uniform
        for (let i = 1; i <= k; i++)
            r += i * Math.floor(unifRand() + 0.5);
        return r;
    });
}
/** Bound on n of rwilcox, and on the m + n ranks held in an array (beyond, the swapped ones in a Map) */
const MAX_RWILCOX_N = 2 ** 24;
/**
 * The sum of n of the ranks 0..k-1 drawn without replacement, as the array version of rwilcox (the same uniforms and
 * the same value) with only the slots that hold another rank than their own kept, in a Map: at most n - 1 of them, as
 * the last draw updates none (an Int32Array of m + n, up to 8 GB, was filled for each value)
 */
function sparseRankSum(k, n) {
    const moved = new Map();
    let r = 0;
    for (let i = 0; i < n; i++) {
        const j = unifIndex(k);
        r += moved.get(j) ?? j;
        k--;
        if (i === n - 1)
            break;
        // x[j] = x[k]; the slot k is out of reach from now on
        if (j !== k)
            moved.set(j, moved.get(k) ?? k);
        moved.delete(k);
    }
    return r;
}
/**
 * Random numbers from the distribution of the Wilcoxon rank sum statistic.
 * Equivalent to R's `rwilcox()`.
 *
 * @param nn Number of values to generate.
 * @param m Number of observations in the first sample.
 * @param n Number of observations in the second sample.
 * @returns An array of `nn` values; `NaN` for invalid parameters.
 * @throws RangeError if `m + n` exceeds 2147483647 or `n` exceeds 2^24 (one uniform is drawn per value of the second
 * sample), before drawing.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rwilcox(5, 4, 6); // [7, 5, 12, 17, 10]
 * ```
 *
 * @category Random numbers
 */
export function rwilcox(nn, m, n) {
    return generate(nn, () => {
        if (Number.isNaN(m) || Number.isNaN(n))
            return NaN;
        // as R's R_forceint (nearbyint): halves go to the even integer
        const mm = roundHalfEven(m);
        const ny = roundHalfEven(n);
        if (mm < 0 || ny < 0)
            return NaN;
        if (mm === 0 || ny === 0)
            return 0;
        // R holds the m + n ranks in an array, whose allocation fails beyond its integer range
        if (!(mm + ny <= 2147483647))
            throw new RangeError("m + n must be at most 2147483647");
        // one uniform per rank drawn (about 3.5 s at 2^24), before drawing
        if (ny > MAX_RWILCOX_N)
            throw new RangeError("n must be at most 2^24 (16777216)");
        // Choose n of 0..m+n-1 without replacement and subtract the minimum n(n-1)/2 from their sum
        let k = mm + ny;
        if (k > MAX_RWILCOX_N)
            return sparseRankSum(k, ny) - (ny * (ny - 1)) / 2;
        const x = new Int32Array(k);
        for (let i = 0; i < k; i++)
            x[i] = i;
        let r = 0;
        for (let i = 0; i < ny; i++) {
            const j = unifIndex(k);
            r += x[j];
            x[j] = x[--k];
        }
        return r - (ny * (ny - 1)) / 2;
    });
}
